// Digest window: from the end of the last digest (workflow static data), capped at 14 days;
// 7 days when there is no usable last end. Advanced only by "Record Window" after delivery.
const DAY = 86400000;
const CAP_MS = 14 * DAY;
const FALLBACK_MS = 7 * DAY;
const now = new Date();
const sd = $getWorkflowStaticData('global');
let start = new Date(now.getTime() - FALLBACK_MS);
if (typeof sd.lastDigestEnd === 'string') {
  const last = new Date(sd.lastDigestEnd);
  if (!isNaN(last.getTime()) && last.getTime() < now.getTime()) {
    start = new Date(Math.max(last.getTime(), now.getTime() - CAP_MS));
  }
}
return [{ json: { windowStart: start.toISOString(), windowEnd: now.toISOString() } }];

// STUB collector (#202 shell). Returns not-deployed until the real source lands (#200, #70).
// Contract: status is one of ok | failed | not-deployed; applied = [{name, from, to}];
// pending = [{name, version}]. A failed source must return status failed, never empty lists.
return [{ json: { source: 'unifi', status: 'not-deployed', reason: 'collector not implemented yet (#200)', applied: [], pending: [] } }];

// STUB collector (#202 shell). Returns not-deployed until the real source lands (#200, #70).
// Contract: status is one of ok | failed | not-deployed; applied = [{name, from, to}];
// pending = [{name, version}]. A failed source must return status failed, never empty lists.
return [{ json: { source: 'os', status: 'not-deployed', reason: 'collector not implemented yet', applied: [], pending: [] } }];

// STUB collector (#202 shell). Returns not-deployed until the real source lands (#200, #70).
// Contract: status is one of ok | failed | not-deployed; applied = [{name, from, to}];
// pending = [{name, version}]. A failed source must return status failed, never empty lists.
return [{ json: { source: 'twingate', status: 'not-deployed', reason: 'collector not implemented yet', applied: [], pending: [] } }];

// STUB collector (#202 shell). Returns not-deployed until the real source lands (#200, #70).
// Contract: status is one of ok | failed | not-deployed; applied = [{name, from, to}];
// pending = [{name, version}]. A failed source must return status failed, never empty lists.
return [{ json: { source: 'pfsense', status: 'not-deployed', reason: 'collector not implemented yet (#70)', applied: [], pending: [] } }];

// Weekly update digest builder. Runs for real under Node in tests/python/test_update_digest.py.
const SOURCES = [
  ['unifi', 'UniFi', 'UniFi Collector'],
  ['os', 'OS packages', 'OS Packages Collector'],
  ['twingate', 'Twingate', 'Twingate Collector'],
  ['pfsense', 'pfSense', 'pfSense Collector'],
];
const STATUSES = ['ok', 'failed', 'not-deployed'];
const DESC_MAX = 4000;   // Discord embed description limit is 4096
const TOTAL_MAX = 5800;  // Discord embed total limit is 6000
const TITLE_MAX = 200;   // Discord embed title limit is 256
const ITEM_MAX = 80;
const REASON_MAX = 120;
const MORE_RESERVE = 24;
const MAX_ITEMS = 100000;  // counts stay true; only the rendered text is cut by fit()
const TZ = 'America/New_York';

// Every device, package, version and reason string goes through clean(): coerced to a string,
// control and bidi characters removed, length capped, markdown escaped (md), and every @ broken so
// nothing can mention anyone.
function clean(v, max, md) {
  let s = '';
  if (typeof v === 'string') s = v;
  else if (typeof v === 'number' || typeof v === 'boolean') s = String(v);
  else if (v !== null && v !== undefined) s = '(invalid)';
  s = s.replace(/[\u0000-\u001f\u007f-\u009f\u200b-\u200f\u202a-\u202e\u2066-\u2069\ufeff]/g, ' ')
       .replace(/\s+/g, ' ').trim().slice(0, max);
  if (md) s = s.replace(/[\\`*_~|>#\[\]()<]/g, '\\$&');
  s = s.replace(/@/g, '@\u200b');
  return s || '?';
}

function list(v) { return Array.isArray(v) ? v.slice(0, MAX_ITEMS) : []; }

function fmt(iso) {
  const d = new Date(iso);
  if (isNaN(d.getTime())) return '?';
  return d.toLocaleDateString('en-US', { timeZone: TZ, month: 'short', day: 'numeric', year: 'numeric' });
}

const win = $('Window').first().json;
const sources = SOURCES.map(([key, label, node]) => {
  let j = null;
  try { j = $(node).first().json; } catch (e) { j = null; }
  const ok = j && typeof j === 'object' && !j.error && STATUSES.includes(j.status);
  const status = ok ? j.status : 'failed';
  const reason = status === 'ok' ? '' : (ok ? j.reason : (j && j.error) || 'no result from collector');
  return {
    key, label, status, reason,
    applied: status === 'ok' ? list(j.applied) : [],
    pending: status === 'ok' ? list(j.pending) : [],
  };
});

const appliedAll = [];
const pendingAll = [];
const notChecked = [];
for (const s of sources) {
  if (s.status !== 'ok') { notChecked.push(s); continue; }
  for (const a of s.applied) appliedAll.push({ label: s.label, a: (a && typeof a === 'object') ? a : { name: a } });
  for (const p of s.pending) pendingAll.push({ label: s.label, p: (p && typeof p === 'object') ? p : { name: p } });
}
const nApplied = appliedAll.length;
const nPending = pendingAll.length;
const nNot = notChecked.length;

function fit(lines, budget) {
  const out = [];
  let used = 0;
  for (let i = 0; i < lines.length; i++) {
    const rest = lines.length - i;
    const add = lines[i].length + 1;
    if (used + add > budget - (rest > 1 ? MORE_RESERVE : 0)) {
      out.push('+' + rest + ' more');
      return { text: out.join('\n'), used: used + 12 };
    }
    out.push(lines[i]);
    used += add;
  }
  return { text: out.join('\n'), used };
}

function render(md) {
  const h = (t) => (md ? '**' + t + '**' : t);
  const c = (v, m) => clean(v, m, md);
  const decision = nApplied + ' applied, ' + nPending + ' still pending, ' + nNot +
    (nNot === 1 ? ' source' : ' sources') + ' not checked';
  const ncLines = notChecked.map((s) => s.label + ': ' + (s.status === 'failed'
    ? 'check failed - ' + c(s.reason, REASON_MAX) : 'not deployed yet'));
  const ncText = ncLines.length ? ncLines.join('\n') : 'All sources checked.';
  const footer = 'Weekly digest, Mondays 07:00 Eastern. A missing digest means the workflow is broken.';
  const fixed = decision.length + ncText.length + footer.length + 120;
  const rem = DESC_MAX - fixed;
  const appLines = appliedAll.map((x) => x.label + ': ' + c(x.a.name, ITEM_MAX) + ' ' +
    c(x.a.from, ITEM_MAX) + ' -> ' + c(x.a.to, ITEM_MAX));
  const penLines = pendingAll.map((x) => x.label + ': ' + c(x.p.name, ITEM_MAX) + ' (' + c(x.p.version, ITEM_MAX) + ')');
  const ap = appLines.length ? fit(appLines, Math.floor(rem / 2)) : { text: 'Nothing applied.', used: 16 };
  const pe = penLines.length ? fit(penLines, rem - ap.used) : { text: 'Nothing pending.', used: 16 };
  let desc = [h('Summary'), decision, '', h('Applied'), ap.text, '', h('Still pending'), pe.text, '',
    h('Not checked'), ncText, '', footer].join('\n');
  if (desc.length > DESC_MAX) desc = desc.slice(0, DESC_MAX - 12) + '\n+ truncated';
  return { desc, decision };
}

const title = ('Weekly update digest: ' + fmt(win.windowStart) + ' to ' + fmt(win.windowEnd) + ' (Eastern)').slice(0, TITLE_MAX);
const md = render(true);
const plain = render(false);
let description = md.desc;
if (title.length + description.length > TOTAL_MAX) description = description.slice(0, TOTAL_MAX - title.length - 12) + '\n+ truncated';
const out = {
  title,
  description,
  color: nNot === 0 ? 3066993 : 15105570,
  allowed_mentions: { parse: [] },
  matrixBody: title + '\n\n' + plain.desc,
  txnId: 'weekly-digest-' + String(win.windowEnd).replace(/[^0-9A-Za-z]/g, ''),
  windowStart: win.windowStart,
  windowEnd: win.windowEnd,
  counts: { applied: nApplied, pending: nPending, notChecked: nNot },
  sources: Object.fromEntries(sources.map((s) => [s.key, s.status])),
};
// ALWAYS-SEND: exactly one item, even on a quiet week, so silence means broken.
return [{ json: out }];

// Advance the window only after delivery. Both channels failing is an error (error workflow fires)
// and leaves the window alone, so the next digest covers the gap (capped at 14 days).
const failed = (name) => {
  try { const j = $(name).first().json; return !!(j && j.error); } catch (e) { return true; }
};
const discordFailed = failed('Discord Digest');
const matrixFailed = failed('Matrix Digest');
if (discordFailed && matrixFailed) {
  throw new Error('weekly update digest: delivery failed on Discord and Matrix; window not advanced');
}
const windowEnd = $('Window').first().json.windowEnd;
$getWorkflowStaticData('global').lastDigestEnd = windowEnd;
return [{ json: { windowEnd, discordOk: !discordFailed, matrixOk: !matrixFailed } }];
